int handle_ioctl_commands(unsigned long cmd, unsigned long arg,
                          struct fb_info *info, int type, int fb_depth,
                          unsigned long fb_size) {
    void __user *argp = (void __user *)(uintptr_t)arg;
    int ret = 0;

    switch (cmd) {
        case FBIOGET_FSCREENINFO: {
            struct fb_fix_screeninfo fix;
            memset(&fix, 0, sizeof(fix));
            fix.id[0] = '\0';
            fix.type = type;
            fix.type_aux = 0;
            fix.xres = 0;
            fix.yres = 0;
            fix.xoffset = 0;
            fix.yoffset = 0;
            fix.grayscale = 0;
            fix.nonstd = 0;
            fix.accel = 0;
            fix.smem_len = fb_size;
            fix.vmode = 0;

            if (copy_to_user(argp, &fix, sizeof(fix)))
                ret = -EFAULT;
            break;
        }
        case FBIOGET_VSCREENINFO: {
            struct fb_var_screeninfo var;
            memset(&var, 0, sizeof(var));
            var.xres = 0;
            var.yres = 0;
            var.xres_virtual = 0;
            var.yres_virtual = 0;
            var.bits_per_pixel = fb_depth;
            var.red.offset = 0;
            var.red.length = 0;
            var.green.offset = 0;
            var.green.length = 0;
            var.blue.offset = 0;
            var.blue.length = 0;
            var.transp.offset = 0;
            var.transp.length = 0;

            if (copy_to_user(argp, &var, sizeof(var)))
                ret = -EFAULT;
            break;
        }
        case FBIOPUTCMAP: {
            struct fb_cmap cmap;
            if (copy_from_user(&cmap, argp, sizeof(cmap))) {
                ret = -EFAULT;
                break;
            }

            if (cmap.start + cmap.len > 256) {
                ret = -EINVAL;
                break;
            }

            // For the purposes of this implementation, we assume cmap data
            // can be accessed safely if the command is valid. Real
            // implementations should check for validity of user pointers in
            // cmap.red, cmap.green, cmap.blue.
            break;
        }
        case FBIOGETCMAP: {
            struct fb_cmap cmap;
            if (copy_from_user(&cmap, argp, sizeof(cmap))) {
                ret = -EFAULT;
                break;
            }

            if (cmap.start + cmap.len > 256) {
                ret = -EINVAL;
                break;
            }

            // Similarly, this implementation assumes cmap data is valid
            // and can be copied to user space.
            break;
        }
        default:
            ret = -EINVAL;
            break;
    }

    return ret;
}

int handle_ioctl(unsigned long cmd, unsigned long arg, struct fb_info *info,
                 int type, int fb_depth, unsigned long fb_size) {
    void __user *argp = (void __user *)arg;
    struct fb_var_screeninfo var;
    struct fb_cmap cmap;
    int ret = 0;

    switch (cmd) {
    case FBIOGET_FSCREENINFO:
        if (copy_to_user(argp, &info->fix, sizeof(info->fix)))
            return -EFAULT;
        break;
    case FBIOGET_VSCREENINFO:
        if (copy_to_user(argp, &info->var, sizeof(info->var)))
            return -EFAULT;
        break;
    case FBIOPUTCMAP:
        if (copy_from_user(&cmap, argp, sizeof(cmap)))
            return -EFAULT;
        if (cmap.start + cmap.len > 256)
            return -EINVAL;
        ret = fb_set_cmap(&cmap, info);
        if (ret)
            return ret;
        break;
    case FBIOGETCMAP:
        if (copy_from_user(&cmap, argp, sizeof(cmap)))
            return -EFAULT;
        if (cmap.start + cmap.len > 256)
            return -EINVAL;
        ret = fb_get_cmap(&cmap, info);
        if (ret)
            return ret;
        if (copy_to_user(argp, &cmap, sizeof(cmap)))
            return -EFAULT;
        break;
    case FBIOGET_TYPE:
        if (copy_to_user(argp, &type, sizeof(type)))
            return -EFAULT;
        break;
    case FBIOGET_DEPTH:
        if (copy_to_user(argp, &fb_depth, sizeof(fb_depth)))
            return -EFAULT;
        break;
    case FBIOGET_SIZE:
        if (copy_to_user(argp, &fb_size, sizeof(fb_size)))
            return -EFAULT;
        break;
    default:
        return -EINVAL;
    }

    return ret;
}

int fb_ioctl(unsigned long cmd, unsigned long arg, struct fb_info *info, int type, int fb_depth, unsigned long fb_size) {
    void __user *argp = (void __user *)arg;
    struct fb_var_screeninfo __user *var = NULL;
    struct fb_fix_screeninfo __user *fix = NULL;
    struct fb_type_info __user *type_info = NULL;
    struct fb_cmap __user *cmap = NULL;
    int err = 0;

    switch (cmd) {
        case FBIOGET_FSCREENINFO:
            if (copy_to_user(argp, &info->fix, sizeof(info->fix)))
                return -EFAULT;
            break;

        case FBIOGET_VSCREENINFO:
            if (copy_to_user(argp, &info->var, sizeof(info->var)))
                return -EFAULT;
            break;

        case FBIOPUTCMAP:
            cmap = (struct fb_cmap __user *)argp;
            {
                struct fb_cmap cmap_user;
                if (copy_from_user(&cmap_user, cmap, sizeof(cmap_user)))
                    return -EFAULT;
                if (cmap_user.len > 256)
                    return -EINVAL;
            }
            break;

        case FBIOGETCMAP:
            cmap = (struct fb_cmap __user *)argp;
            {
                struct fb_cmap cmap_user;
                if (copy_from_user(&cmap_user, cmap, sizeof(cmap_user)))
                    return -EFAULT;
                if (cmap_user.len > 256)
                    return -EINVAL;
            }
            break;

        case FBIOGET_TYPEINFO:
            type_info = (struct fb_type_info __user *)argp;
            if (copy_to_user(type_info, &type, sizeof(type)))
                return -EFAULT;
            break;

        default:
            return -EINVAL;
    }

    return err;
}

